WFJ.Data.add("book", {
  ["a0008af2a9560c66"] = { "Nataka、Thousand Needlesは万事順調だ。centaurは厄介なだけで、それ以上のものではない……時おり襲ってはくるが、本当の脅威と呼べるほどのものではない。ただ、centaurの氏族が団結しつつあるという知らせもあるようだ。\n\n我々はいつも、centaurのような冷酷な種族が団結したらどうなるかと考えてきた……知ってのとおり、私はそういう考えにとらわれないようにしている……奴らが抱く純粋な憎しみは何ものにも揺るがない……互いに対してさえもだ。\n\n-Cliffwatcher Longhorn", "." },
  ["a00898d6e040d99e"] = { "Age of Memoryより前、優しきEarthmotherは夜明けの黄金の霧に息を吹きかけた。琥珀色の雲が降り立った場所には、波打つ小麦と大麦の果てしない野が広がった。これこそが彼女の御業の盆地――生命と希望の大いなる籠であった。", "." },
  ["a0405b7a8ab0f5b0"] = { "数で劣り、血の渇きの呪いに狂わされたオークは、必然的にAllianceの怒りの前に倒れた。Doomhammerは捕虜としてLordaeronへ護送され、崩壊した氏族は一網打尽にされて北へ――Lordaeronへと連行された。", "." },
  ["a04791a122b5523a"] = { "同胞よ、このルーンが無事に届くことを願っている。Coldridge Valleyを見下ろすAnvilmarの中に俺がいることを、ちょっと知らせておきたくてな。\n\n俺たちが団結することがどれほど大事か、俺にはわかっている。平和が張り詰めているこのご時世、仲間がそばにいることはますます大事になってきている。時間があるときに俺を探してくれ。\n\n-ローグのトレーナー、Solm Hargrin", "." },
  ["a05ff2af11958927"] = { "堕落したCaptain Redpathは、その邪悪な穢れをDarrowshireの守り手たちの間に広めた。守り手たちは味方を裏切り、彼らを虐殺した。そして次にDarrowshireの町へと矛先を向け、家に隠れていた者を皆殺しにした。\n\n残るScourgeの軍勢は、堕落したCaptain Redpathの魂と共に、荒れ果てたDarrowshireの村を後にしてLordaeronへとなだれ込み、Second Warの苦痛と死をさらに増やしたのである。", "." },
  ["a0774b7ba86716ec"] = { "しかし、Stormwindの貴族たちは、ElwynnからStranglethornにまで王国の軍事的存在を広げたことで莫大な負債を抱えました。その莫大な負債は王国の経済を麻痺させ、VanCleefとStonemasonsから約束された報酬を奪ったのです。輝かしい都の再建に何年も身を粉にして働いた末、Stonemasonsは無一文のまま、都の腐敗した役人たちに忘れ去られました。", "." },
  ["a093b764fdff4be2"] = { "トーレンの故郷にこれほど近い場所での大規模な事業ですから。しかし、彼らがこの地域における当社の全体的な事業計画の大きな障害になるとは考えておりません。\n\n鉱物の豊富なMulgoreの平原で採掘が始まったと聞き、喜ばしく思っております。これを受けて、委員会は貴殿の機材請求を承認いたしました。採掘に加えて、Mulgoreは木材の面でも大いに見込みがあると考えておりますので、当社の最新型シュレッダー数台と、建設用の原材料も併せて支給いたします。", "." },
  ["a097bea45850d7f8"] = { "魔法の森の古木が根こそぎにされ倒れると、大地は震えた。Cenariusの息子や娘たちが守る木立や林も、星の子らの石の塔も、揺れ動く大地に崩れ落ちた。そこには我らが女王がいた。絶望の中にあっても、戦いの混沌の中にあっても光り輝いて。魔法の放出と、世界を引き裂かんとする爆発によって、魔法の空は色を変えた。\n\n兄弟が兄弟と戦った。選ばれし者が", "." },
})
